#include <cstddef>
struct SameHash {
    std::size_t operator()(int) const { return 0; }
};
int main() {
    std::unordered_map<int, int, SameHash> m;
    for (int n = 0; n < 16; ++n) {
        m.emplace(n, n * n);
    }
    int sum = 0;
    for (int n = 0; n < 16; ++n) {
        auto p = m.find(n);
        if (p == m.end() || p->second != n * n) {
            return 2;
        }
        sum += p->second;
    }
    m.erase(7);
    std::cout << sum << ' ' << m.size() << ' ' << (m.find(7) == m.end())
              << '\n';
}

