#include <iostream>
#include <algorithm>
#include <map>
#include <string>
#include <vector>

int main() {
    int n;
    if (!(std::cin >> n) || n < 0 || n > 64) {
        std::cout << "invalid\n";
        return 0;
    }
    std::vector<std::string> words;
    for (int i = 0; i < n; ++i) {
        std::string word;
        if (!(std::cin >> word) || word.size() > 12 ||
            !std::all_of(word.begin(), word.end(),
                         [](char ch) { return ch >= 'a' && ch <= 'z'; })) {
            std::cout << "invalid\n";
            return 0;
        }
        words.push_back(word);
    }
    std::cin >> std::ws;
    if (!std::cin.eof()) {
        std::cout << "invalid\n";
        return 0;
    }

    if (words.empty()) {
        std::cout << "empty\n";
        return 0;
    }
    std::map<std::string, int> counts;
    // TODO: Add each word to the map and increment its count for every
    // occurrence.
    for (const auto &[word, count] : counts) {
        std::cout << word << ' ' << count << '\n';
    }
}

